WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM payments), sessions_payments AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, method, amount, paid_at, is_new_session, CASE WHEN method RLIKE '^(cash|promptpay)$' THEN 'GROUP_B' WHEN method RLIKE '^(card|paypal)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS method_zone FROM sessions_payments ORDER BY method_zone ASC NULLS LAST, id ASC
